using System;
using System.Collections.Generic;

public static class Callbacks
{
    // The i-th thunk should return i.
    // BUG: a `for` loop captures the SAME variable i in every closure, so all
    // thunks return the final value of i (== count).
    public static List<Func<int>> Build(int count)
    {
        var result = new List<Func<int>>();
        for (int i = 0; i < count; i++)
        {
            result.Add(() => i);
        }
        return result;
    }
}

