using System.Linq;
using Xunit;

public class CallbacksTests
{
    [Fact]
    public void EachThunkReturnsItsIndex()
    {
        var thunks = Callbacks.Build(3);
        Assert.Equal(new[] { 0, 1, 2 }, thunks.Select(t => t()).ToArray());
    }

    [Fact]
    public void SingleThunk()
    {
        Assert.Equal(new[] { 0 }, Callbacks.Build(1).Select(t => t()).ToArray());
    }

    [Fact]
    public void EmptyWhenZero()
    {
        Assert.Empty(Callbacks.Build(0));
    }
}

