using System;
using System.Collections.Generic;

public static class Callbacks
{
    // Fixes the capture but returns index+1 instead of index.
    public static List<Func<int>> Build(int count)
    {
        var result = new List<Func<int>>();
        for (int i = 0; i < count; i++)
        {
            int captured = i + 1;
            result.Add(() => captured);
        }
        return result;
    }
}
